INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 6, 'theory', 'Quiz: consistency and idempotency');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 0, 'According to the CAP theorem, what does a system choose between during a network partition?', '["Between speed and cost", "Between consistency and availability", "Between two regions", "Between reads and writes"]', 1, 'Partitions are unavoidable; for the duration of the failure, the system either refuses to answer (C) or answers with possibly stale data (A).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 1, 'Why is “exactly once” implemented in practice as “at least once” plus idempotency?', '["It is cheaper to store", "Pure exactly-once delivery is unattainable in a distributed system", "That is how protocols do it", "It is faster"]', 1, 'Messages can be duplicated; an idempotent receiver makes the effect equal to a single one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 2, 'Which operation is idempotent?', '["balance = balance + 100", "set the order status to “paid”", "append a record to a log", "send an email"]', 1, 'Setting a value gives the same result on repeat; adding accumulates.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 3, 'Why are retries without a pause dangerous when a service is overloaded?', '["They aren''t", "They worsen the overload: load multiplies and the service cannot recover", "They speed up the response", "They reduce latency"]', 1, 'A retry storm: clients multiply the load; you need a growing pause, jitter, a retry budget, and a circuit breaker.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 4, 'What is a saga for?', '["For encryption", "For a long operation across several services: steps with compensating actions instead of locks", "For caching", "For load balancing"]', 1, 'A saga is a chain of local transactions; on failure, compensations run in reverse order.');
